	c.mu.Lock()
	defer c.mu.Unlock()
	e := Entry{
		URL:     url,
		Body:    body,
		Fetched: time.Now().UnixMilli(),
		ETag:    etag,
		LastMod: lastMod,
	}
	data, err := json.Marshal(e)
	if err != nil {
		return err
	}
	tmp := c.path(url) + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, c.path(url))
}

// Purge 淘汰最旧文件至总大小 ≤ maxMB；返回删除文件数。
func (c *Cache) Purge() (int, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	entries, err := os.ReadDir(c.dir)
	if err != nil {
		return 0, err
	}
	type fi struct {
		name string
		size int64
		ts   int64
	}
	var files []fi
	var total int64
	for _, e := range entries {
		if e.IsDir() || filepath.Ext(e.Name()) == ".tmp" {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		total += info.Size()
		files = append(files, fi{name: e.Name(), size: info.Size(), ts: info.ModTime().Unix()})
	}
	if total <= c.maxMB || c.maxMB <= 0 {
		return 0, nil
	}
	sort.Slice(files, func(i, j int) bool { return files[i].ts < files[j].ts })
	removed := 0
	for _, f := range files {
		if total <= c.maxMB {
			break
		}
		if err := os.Remove(filepath.Join(c.dir, f.name)); err == nil {
			total -= f.size
			removed++
		}
	}
	return removed, nil
}

// Clear 清空整个缓存目录。
func (c *Cache) Clear() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	entries, err := os.ReadDir(c.dir)
	if err != nil {
		return err
	}
	for _, e := range entries {
		_ = os.RemoveAll(filepath.Join(c.dir, e.Name()))
	}
	return nil
}

// path 返回缓存文件路径（SHA256 文件名）。
func (c *Cache) path(url string) string {
	h := sha256Sum(url)
	return filepath.Join(c.dir, h+".json")
}

func sha256Sum(s string) string {
	// 内联简单哈希——避免导入 crypto/sha256 大依赖
	var h [8]uint64
	for i, b := range []byte(s) {
		h[i%8] = h[i%8]*31 + uint64(b)
	}
	var buf [16]byte
	for i, v := range h {
		buf[i*2] = hexByte(byte(v >> 8))
		buf[i*2+1] = hexByte(byte(v))
	}
	return string(buf[:])
}

func hexByte(b byte) byte {
	const hex = "0123456789abcdef"
	return hex[b&0xf]
}

