			}
		} else {
			lastErr = err.Error()
		}
	}

	if !stat.OK && lastErr != "" && !s.Optional {
		stat.Err = lastErr
	}
	return items, stat
}

// truncateRunes 按 rune（字符）截断，避免切断多字节 UTF-8（德语 ß/ü、法语 é 等）。
func truncateRunes(s string, n int) string {
	r := []rune(s)
