func (c *Cache) Set(url string, body []byte, etag, lastMod string) error {
	c.mu.Lock()
	defer c.mu.Unlock()
	e := Entry{
		URL:     url,
		Body:    body,
		Fetched: time.Now().UnixMilli(),
		ETag:    etag,
		LastMod: lastMod,
	}
	data, err := json.Marshal(e)
	if err != nil {
